package pricing

import "testing"

func TestCartTotal(t *testing.T) {
	tests := []struct {
		name string
		cart Cart
		want int
	}{
		{
			name: "empty cart",
			cart: Cart{Discount: &Discount{Percent: 10}},
			want: 0,
		},
		{
			name: "sums price times quantity across items",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 150, Qty: 4},
					{Name: "book", Cents: 1299, Qty: 1},
				},
				Discount: &Discount{Percent: 0},
			},
			want: 1899,
		},
		{
			name: "applies percent discount to the sum",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 150, Qty: 4},
					{Name: "book", Cents: 1299, Qty: 1},
				},
				Discount: &Discount{Percent: 20},
			},
			want: 1520,
		},
		{
			name: "fractional discount cent is not taken off",
			cart: Cart{
				Items:    []*Item{{Name: "mug", Cents: 999, Qty: 1}},
				Discount: &Discount{Percent: 10},
			},
			want: 900,
		},
		{
			name: "no discount charges full price",
			cart: Cart{
				Items: []*Item{{Name: "mug", Cents: 999, Qty: 2}},
			},
			want: 1998,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.cart.Total(); got != tt.want {
				t.Errorf("Total() = %d, want %d", got, tt.want)
			}
		})
	}
}

func TestApplyDiscount(t *testing.T) {
	tests := []struct {
		name           string
		cents, percent int
		want           int
	}{
		{"zero percent", 1000, 0, 1000},
		{"partial percent", 1000, 25, 750},
		{"truncates fractional cent of discount", 999, 10, 900},
		{"full percent", 1000, 100, 0},
		{"percent above 100 is capped at zero", 1000, 150, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := ApplyDiscount(tt.cents, tt.percent); got != tt.want {
				t.Errorf("ApplyDiscount(%d, %d) = %d, want %d", tt.cents, tt.percent, got, tt.want)
			}
		})
	}
}

